insert into public.reg_area (id, authority, kind, name, parent_id, boundary_geojson, source_url, verified_at, notes) values
  ('ca-gma-northern', 'cdfw', 'groundfish_management_area', 'Northern GMA — California-Oregon border to Cape Mendocino (40°10′ N)', null, null, 'https://wildlife.ca.gov/Fishing/Ocean/Regulations/Groundfish-Summary', '2026-09-01', 'CCR T14 §27.25(a). Same ring as the pack envelope; GMA rules carry the 2026 season table.'),
  ('ca-gma-mendocino', 'cdfw', 'groundfish_management_area', 'Mendocino GMA — Cape Mendocino (40°10′ N) to Point Arena (38°57.5′ N)', null, null, 'https://wildlife.ca.gov/Fishing/Ocean/Regulations/Groundfish-Summary', '2026-09-01', 'CCR T14 §27.30(a). 2026 table identical to Northern.'),
  ('ca-gma-san-francisco', 'cdfw', 'groundfish_management_area', 'San Francisco GMA — Point Arena (38°57.5′ N) to Pigeon Point (37°11′ N)', null, null, 'https://wildlife.ca.gov/Fishing/Ocean/Regulations/Groundfish-Summary', '2026-09-01', 'CCR T14 §27.35(a). Cordell Bank: ALL groundfish fishing prohibited inside (NMFS compliance guide, June 2026).'),
  ('ca-gma-central', 'cdfw', 'groundfish_management_area', 'Central GMA — Pigeon Point (37°11′ N) to Point Conception (34°27′ N)', null, null, 'https://wildlife.ca.gov/Fishing/Ocean/Regulations/Groundfish-Summary', '2026-09-01', 'CCR T14 §27.40(a). South of here the SoCal pack''s Southern GMA season table rules.')
on conflict (id) do nothing;

