insert into public.reg_rule
  (species_id, reg_group_id, reg_area_id, water_class, kind, verbatim, source_url, source_title, source_updated_at, verified_at, pack_version,
   season_start, season_end, bag_daily, possession_limit, min_size_in, max_size_in, size_measure, platform_scope, depth_note, check_inseason, stale_after_days)
values
  (null, null, 'ca-gma-southern', 'salt', 'note', 'It is unlawful to possess a groundfish species or species group within a Groundfish Management Area where the take and possession of those species are prohibited in all waters of that Groundfish Management Area or in excess of the bag limit of that Groundfish Management Area, regardless of if the groundfish species or species group were taken in a different Groundfish Management Area where the take or possession is authorized (CCR T14 §27.20(b)(1)(A)(1)).', 'https://wildlife.ca.gov/Fishing/Ocean/Regulations/Groundfish-Summary', 'CDFW — Summary of Recreational Groundfish Fishing Regulations (updated June 23, 2026)', '2026-06-23', '2026-09-01', 2,
   null, null, null, null, null, null, null, null, null, false, 60),
  (null, null, 'ca-gma-southern', 'salt', 'note', 'Transit Provision: in waters where groundfish species or species groups are closed to take or possession but authorized elsewhere, those species may be possessed aboard a vessel that is anchored, drifting, or transiting in or through the closed area. While transiting a closed area, no gear may be deployed other than crustacean hoop nets (§29.80(b)), Dungeness crab traps (§29.80(c)), and dip nets (§28.80) (CCR T14 §27.20(b)(1)(A)).', 'https://wildlife.ca.gov/Fishing/Ocean/Regulations/Groundfish-Summary', 'CDFW — Summary of Recreational Groundfish Fishing Regulations (updated June 23, 2026)', '2026-06-23', '2026-09-01', 2,
   null, null, null, null, null, null, null, null, null, false, 60),
  (null, null, 'ca-gma-southern', 'salt', 'note', 'Groundfish Exclusion Areas: eight Groundfish Exclusion Areas in the Southern Management Area restrict certain fishing activities (CCR T14 §27.50). Cowcod protections — take of groundfish is prohibited inside the GEAs; coordinates on the CDFW Cowcod page and Ocean Sport Fishing interactive map.', 'https://wildlife.ca.gov/Conservation/Marine/Cowcod', 'CDFW — Cowcod conservation / Groundfish Exclusion Areas', null, '2026-09-01', 2,
   null, null, null, null, null, null, null, null, null, false, 60);

insert into public.reg_pack (id, version, published_at, notes) values
  ('norcal-2026-09-01', 2, '2026-09-01T12:00:00Z', 'Northern California (CDFW, Groundfish Summary updated June 23 2026): v2 adds the GMA layer — Northern, Mendocino, San Francisco and Central Groundfish Management Areas are now first-class areas with their own season windows (identical 2026 tables, verbatim), Cordell Bank prohibition, and the GMA-crossing possession rule. Saltwater only; river/salmon checks stay check-in-season.'),
  ('socal-2026-09-01', 2, '2026-09-01T00:00:00.000Z', 'Hand-verified starter set + v2 Groundfish Management Area doctrine rows (GMA-crossing possession, transit provision, GEA note) from the Groundfish Summary updated June 23, 2026.')
on conflict (id) do update set version = excluded.version, notes = excluded.notes;
